internal object DuaKokDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_new_moon" to DuaText("नवा चंद्र पळोवप", "हे अल्लाह, हो चंद्र आशीर्वाद, श्रद्धा, सुरक्षीतताय आनी इस्लाम घेवन आमचेर उगमपाक दिवचो. (चंद्र,) म्हजो प्रभू आनी तुमचो रब अल्लाह आसा.", "अमावस्या पळोवन.", "दर नव्या म्हयन्याक सुन्नत दुआ."),
        "dua_janaza_adult" to DuaText("जनाझा प्रार्थना (प्रौढ)", "हे अल्लाह, आमचे जिवीत आनी आमचे मेल्ले, हाजीर आनी गैरहाजीर आशिल्ले, आमचे तरणाटीं आनी म्हारग, आमचे दादले आनी बायलो हांकां माफ कर. हे अल्लाह, तूं आमच्या मदलो कोण जिवीत दवरतलो, ताका इस्लाम धर्माविशीं जिवीत दवर, आनी आमच्या मदलो कोणाकूय तूं मरयता, ताका श्रद्धेचेर मरण हाड.", "अंत्यविधीच्या प्रार्थनेच्या तिसऱ्या तकबीरा उपरांत.", "मेल्ल्या प्रौढ व्यक्ती खातीर सुन्नत दुआ."),
        "dua_janaza_child" to DuaText("जनाझा प्रार्थना (भुरगें)", "हे अल्लाह, ताका आमचे खातीर अग्रदूत (आनी आश्रयदातो) कर, ताका आमच्यासाठी इनाम आनी खजिना कर, आनी ताका आमचे खातीर मध्यस्थ कर, जाची मध्यस्थी मान्य जाता.", "भुरग्याच्या अंत्यविधीच्या प्रार्थनेंत (चलये खातीर'इज'ल्हा'अशें म्हणटात).", "हनाफींनी सुन्नत दुआ पाळली."),
        "dua_mayyit_awf" to DuaText("मरण पाविल्ल्या लोकांखातीर सविस्तर दुआ", "हे अल्लाह, ताका माफ कर, ताचेर दया कर, ताका कल्याण कर आनी ताका माफ कर. ताचो स्वागत सन्मानीत कर आनी ताची कबर प्रशस्त कर, ताका उदक, बर्फ आनी गारपीटान धुव, आनी धव्या वस्त्रांतल्यान घाण निवळ जाता अशे तरेन ताका पापांतल्यान निवळ कर.", "अंत्यविधीच्या प्रार्थनेंत वा मेल्ल्या व्यक्ती खातीर.", "तो मेल्लो मनीस आसचो अशी आवफ इब्न मलिक (आर. ए.) हाची इत्सा आशिल्ली."),
        "dua_visiting_graves" to DuaText("कबरेक भेट दिवप", "हे ह्या घरांतल्यो आस्तीक आनी मुसलमान रावपी लोकां, तुमचेर शांती आसची. आमीय, अल्लाह जाय जाल्यार, तुमच्याय वांगडा येतले. हांव अल्लाहाक आमचे खातीर आनी तुमचें कल्याण करपाची विनवणी करता.", "कबरे भितर प्रवेश करतना.", "थडग्यांक भेट दिवप मरणाची आनी परकाळाची याद करून दिता."),
        "dua_closing_eyes" to DuaText("मरणिल्ल्या व्यक्तीचीं दोळे बंद केल्यार", "हे अल्लाह, माफ कर, मार्ग दाखोवप्यां मदीं ताचो दर्जो उंचाव, तो फाटीं सोडपी लोकां मदीं ताचो उत्तराधिकारी जाव. हे जगाच्या स्वामी, आमकां आनी ताका माफ कर, ताची कबर प्रशस्त कर आनी तातूंत उजवाडाचो भर घाल.", "मरणिल्ल्या व्यक्तीचे दोळे बंद करतना (ताच्या नांवाचो उल्लेख करतना).", "पैगंबर सल्ल्याह अलियाह वस्लमान अबू सलामाह (रा.) खातीर ही दुआ केली."),
        "dua_condolence" to DuaText("शोक व्यक्त (ताझिया)", "ताणें जें घेतलें तें निश्चीतपणान अल्लाहचें आसा आनी ताणें जें दिलें तें ताचेच आसा, आनी ताचे कडेन आशिल्ल्या दरेक गोष्टीची एक थारावीक मुदत आसता, देखून धीर धर आनी प्रतिदानाची आस्त दवर.", "मरणा उपरांत एका कुटुंबाक शोक व्यक्त करप.", "पैगंबर सल्लल्लाह अलीह वसलमान आपल्या चलयेक हो संदेश धाडलो."),
        "dua_placing_in_grave" to DuaText("मरण पाविल्ल्या व्यक्तीक कबरे भितर दवरप", "अल्लाहच्या नांवान आनी अल्लाहच्या पैगंबरांच्या मार्गांत.", "जेन्ना मेल्ल्यान कबरेक उडोवपाक.", "दफन करपाचें सुन्नत दुआ."),
        "dua_sneezing" to DuaText("शिंको येवप.", "सगळ्यो तोखणाय अल्लाहाक आसा.-अल्लाह तुज्याचेर दया कर.-अल्लाह तुजें मार्गदर्शन करचो आनी तुजें काम सारकें करचो.", "शिंको येता तेन्ना आयकुपारो'यारहामुकल्ला \"म्हणटा, मागीर शिंको दिवपी जाप दिता.", "मुसलमानाक दुसऱ्या मुस्लिमाचेर हो एक हक्क आसा."),
        "dua_toilet_enter" to DuaText("शौचालयांत प्रवेश करप", "अल्लाहच्या नांवान. हे अल्लाह, हांव अशुद्ध जिन आनी बायले कडल्यान तुका आलाशिरो मागता.", "संडासांत पावचे पयलीं दावो पांय घेवन.", "बिस्मिल्लाह हो जिन्न आनी व्यक्ती हांचे मदलो पडदो जाता."),
        "dua_toilet_exit" to DuaText("शौचालय सोडप", "(हे अल्लाह) हांव तुजी माफी मागता.", "उजवो पांय घेवन संडासांतल्यान भायर सरतना.", "पैगंबर सल्ल्याह अलियाह वसलमान संडासांतल्यान भायर सरतना हें सांगलें."),
        "dua_thanking" to DuaText("कोणाकूय उपकार सांगप", "अल्लाह तुमकां बरे गुण दिवंक दे.", "जेन्ना कोणूय तुमचेर उपकार करता.", "कोण अशें म्हणटा ताणें आपली पुराय उपकारस्तुति व्यक्त केल्या."),
        "dua_love_for_allah" to DuaText("जेन्ना कोण तरी म्हणटा'आय लव्ह यू फॉर अल्लाह'", "तो (अल्लाह), जाचे खातीर तूं म्हजेचेर मोग करता, तो तुजेचेर मोग करचो.", "जेन्ना कोण तरी'अल्लाहाक लागून हांव तुज्याचेर मोग करता'अशें म्हणटा.", "अल्लाहाक लागून आशिल्ल्या मोगाक सुन्नत जाप दिता."),
        "dua_seeing_muslim_smile" to DuaText("नमस्कार (सलाम)", "तुमचेर शांती आसची, आनी अल्लाहची दया आनी ताचो आशीर्वाद आसचो.", "जेन्ना मुसलमानाक मेळटा.", "पुराय सलाम म्हणल्यार तीस बरी कृती मेळटात."),
        "dua_dressing" to DuaText("कपडे घालप", "सगळ्यो तोखणाय अल्लाहाक आसा, जाणें म्हाका हें कपडे घातलें आनी म्हज्या वटेनच्यान कसलीच बळ वा शक्ती नासतना म्हाका तें दिलें.", "कपडे घालतना.", "फाटल्या पापांची माफी मेळपाची आनंदाची खबर."),
        "dua_rooster_donkey" to DuaText("कोंबडें वा गाढव आयकुपाक", "हे अल्लाह, हांव तुज्या कृपे विशीं (कोंबडें) मागता.-हांव शापित (गाढव) शयताना कडल्यान अल्लाहाक आलाशिरो मागता.", "कोंबडें आयकल्यान अल्लाहाक उपकार मागात; गाढवाचो गांडो आयकल्यान शयतना कडेन आलाशिरो घेयात.", "कोंबड्याक एक देवदूत दिसता आनी गाढवाक एक सैतान दिसता."),
        "dua_something_liked" to DuaText("प्रशंसनीय कितें तरी पळोवप (वायट दोळ्यांआड)", "अल्लाहान कितें जाय तें. हे अल्लाह, ताका आशीर्वाद दिवचो.", "कोणाकूय कितें तरी तोखणाय करपा सारकें दिसल्यार, आशिर्वाद मेळोवपाची प्रार्थना करात.", "आशिर्वाद मेळोवपाची प्रार्थना केल्यार वायट दोळे आडावंक शकतात."),
        "dua_sell_buy_debt_repaid" to DuaText("कर्ज परत फारीक करतना", "अल्लाह तुज्या कुटुंबांत आनी तुज्या संपत्तीचेर आशीर्वाद दिवचो.", "रीण परतफेड करतना रिणदात्या खातीर.", "रिणाचें परतावे म्हळ्यार उपकार आनी परतफेड."),
        "dua_talbiyah" to DuaText("तालबिया", "हे अल्लाह, हांव हांगा आसा. हांव हांगा आसा, तुका कोणूच भागीदार ना, हांव हांगा आसा. सगळ्यो तोखणाय, आशीर्वाद आनी राज्य तुमचेंच. तुमकां कोणूच भागीदार ना.", "इहरामांत भितर सरतकच मोठ्यान.", "हज आनी उमरहाचें प्रतीक."),
        "dua_yamani_hajar" to DuaText("रुकन यामनी आनी हजार असवाड हांचे मदीं", "म्हज्या देवा, आमकां ह्या संवसारांत बरें आनी आख़िरतांत बरें दिवचें, आनी उज्याच्या ख्यास्तेकडल्यान आमची राखण करची.", "तवाफांत, येमेनी कॉर्नर आनी ब्लॅक स्टोन हांचे मदीं.", "पैगंबर सल्ल्याह अलियाह वसलमान हे सुवातेर तवाफांत हें पठिल्लें."),
        "dua_safa_marwa" to DuaText("सफा आनी मारवाह हांचे विशीं", "अल्लाह सोडून कोणाकूच पुजा करपाचो अधिकार ना, एकलो, भागीदार नासतना. ताचेंच राज्य आनी तोखणाय, आनी सगळ्या गजालींचेर ताका अधिकार आसा. फकत अल्लाह सोडून कोणाकूच पुजा करपाचो अधिकार ना; ताणें आपलें उतर पुराय केलें, आपल्या सेवकाक मदत केली आनी एकलोच संघाची हार केली.", "सफा चडप आनी किब्लाक तोंड दिवप (तीन फावटीं).", "सफा आनी मारवाह ह्या विशयांत पैगंबर सल्ल्याह अलियाह वसलमाचो दिकर."),
        "dua_arafah" to DuaText("अराफा दिसाचो सगळ्यांत बरो दुआ", "फकत अल्लाह सोडून कोणाकूच पुजा करपाचो हक्क ना, फकत एकलो, भागीदार नासतना. राजवट ताचीच आसा आनी तोखणाय ताचीच आसा, आनी तो सगळ्या गजालींचेर प्रभुत्व दवरपी आसा.", "अराफ्याचो दीस-सगळ्यांत बरो दुआ.", "अराफा दिसाचो दुआ हो सगळ्यांत बरो दुआ, आनी हे सगळ्यांत बरे उतर."),
        "dua_takbeer_tashreeq" to DuaText("तकबीर-ए-तश्रीक", "अल्लाह सगळ्यांत व्हडलो, अल्लाह सगळ्यांत व्हडलो. अल्लाह सोडून हेर देव ना. अल्लाह सगळ्यांत व्हडलो, अल्लाह सगळ्यांत व्हडलो, आनी सगळ्यो तोखणाय अल्लाहाक आसा.", "9 धुल-हिज्जाच्या फजर ते 13 धुल-हिज्जाच्या असर मेरेन दर एका सक्तीच्या प्रार्थने उपरांत.", "अली आनी इब्न मसूद (आर. ए.) हांचे कडल्यान अहवाल मेळ्ळो-हनाफींच्या मतान वाजिब."),
        "dua_zamzam" to DuaText("जामझम पिवप", "हे अल्लाह, हांव तुका फायद्याचें गिन्यान, भरपूर पुरवण आनी दरेक दुयेंसावयल्यान उपचार मागता.", "जमजम पिवतना तुका कितेंय जाय ताचे खातीर दुआ कर.", "जमजम जें कितें पियेल्ल्यान जाता ताचे खातीर आसता (इब्न माजाह 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("सृष्टीचेर चिंतन करप", "म्हज्या प्रभू, तूं हें सगळें व्यर्थ निर्माण करूंक ना. तो म्हान आसा, देखून उज्याच्या ख्यास्तेकडल्यान आमची राखण कर.", "स्वर्ग आनी धर्तरेच्या निर्मितीचेर चिंतन करपी लोकांचें दुआ.", "समजदार लोकांचें दुआ (उलुल-अलबाब)."),
        "dua_q_sami_na_munadiyan" to DuaText("आमी विश्वासाक फोन करपी आयकलो", "म्हज्या प्रभू, आमी एका फोन करपीक'तुझ्या प्रभूचेर विश्वास दवर \"अशें म्हणपी आयकलो, आनी आमी विश्वास दवरलो. हे म्हज्या प्रभू, आमचे पापां माफ कर, आमचे पापां आमच्या कडल्यान पयस कर आनी आमकां धर्मीकां वांगडा मरण हाड.", "धर्मीक लोकां मदीं विश्वास आनी मरणा खातीर एक दुआ.", "क्षमा आनी बरो शेवट मेळोवपा खातीर दुआ."),
        "dua_q_atina_ma_waadtana" to DuaText("तूं कितें उतर दिल्लो तें आम्हांक दिव.", "म्हज्या प्रभू, तूं आपल्या दूतां वरवीं आम्हांक जे उतर दिलें तें आम्हांक दिव. आनी पुनरुत्थान दिसा आमची बदनामी करची न्हय. तूं तुजें उतर मोडना.", "पुनरुत्थान दिसा अपमानाक शरण घेवचें.", "परतीच्या काळांत मान मेळोवपाची इत्सा."),
        "dua_q_israfana" to DuaText("आमचे अतिरेक माफ कर", "म्हज्या देवा, आमचे पाप आनी आमच्या बाबतींत आमचे अतिरेक माफ कर, आमचे पांय घट कर आनी अविश्वास करपी लोकां आड आमची मदत कर.", "आदल्या पयलींच्या पैगंबरांच्या साथीदारांची दुआ.", "स्थैर्य आनी क्षमा करपा खातीर एक दुआ."),
        "dua_q_jamiun_nas" to DuaText("तूं मनशांक एकठांय करतलो.", "म्हज्या प्रभू, ज्या दिसा तूं मनशाक एकठांय करतलो, ताचे विशीं दुबाव आसचो ना. खरें म्हणल्यार, अल्लाह आपलें उतर मोडना.", "पुनरुत्थान दिसा निश्चीतताय मेळोवप.", "गिन्यानांत खरपणान आदारिल्ल्या लोकांचो दुआ."),
        "dua_q_maash_shahidin" to DuaText("साक्षीदारां मदीं आमकां बरोव.", "म्हज्या देवा, आमी विश्वास दवरला, देखून आमी साक्षीदारां मदीं बरो.", "सत्य वळखून ताचेर विस्वास दवरपी लोकांचो दुआ.", "स्वताचो विश्वास मान्य करपा खातीर एक दुआ."),
        "dua_q_la_tajalna_zalimin" to DuaText("चुकीच्या लोकां कडेन न्हय", "म्हज्या देवा, आमकां अन्याय करपी लोकां वांगडा दवरचो न्हय.", "अल-अराफाच्या लोकांची दुआ.", "अपराधी लोकांच्या भवितव्या पसून शरण घेवचें."),
        "dua_q_tawaffana_muslimin" to DuaText("मुसलमान म्हणून धीर आनी मरण", "म्हज्या देवा, आमचेर धीर दवर आनी मुसलमान म्हूण मरण हाड.", "फारोच्या जादूगारांचो दिवा जेन्ना तांणी विश्वास दवरलो.", "कसोटींत धीर धरप आनी श्रद्धेचो शेवट करप."),
        "dua_q_la_tajalna_fitnah" to DuaText("जुलमी लोकांचेर खटला न्हय", "आमी अल्लाहचेर भरवंसा दवरतात. आमच्या प्रभू, अन्याय करपी लोकांखातीर आमची परिक्षा करची न्हय, आनी तुज्या दयेन अविश्वास करपी लोकां पसून आमची सुटका कर.", "मुसा (ए. एस.) च्या लोकांची दुआ.", "जुलाम आनी जुलमी लोकां पसून वाटावपा खातीर एक दुआ."),
        "dua_q_nuh_ma_laysa_li" to DuaText("क्षमा करपा खातीर नूहाचो दुआ (ए. एस.)", "म्हज्या प्रभू, म्हाका खबर नाशिल्ल्या गजालीं खातीर तुजे कडेन मागपा पसून हांव तुका आलाशिरो मागता. आनी तूं म्हाका माफ करिनासतना आनी म्हज्याचेर दया करिनासतना हांव लुकसाण करपी लोकां मदीं आसतलो.", "पैगंबर नूह (अ. स.) हाच्या पश्चात्तापाची दुआ.", "योग्य रितीन विचारपाचो एक धडा."),
        "dua_q_mudkhala_sidq" to DuaText("सत्याचो प्रवेश आनी भायर सरप", "म्हज्या देवा, म्हाका सत्या वांगडा प्रवेश कर आनी सत्या वांगडा भायर सरपाक दिव, आनी म्हाका तुज्या कडल्यान आदार दिवपी अधिकार दिव.", "नवें काम करचे पयलीं, घर वा सुवात.", "दुआ हिजरताच्या वेळार पैगंबर सल्ल्याह अलियाह वसलमाक शिकयतालो."),
        "dua_q_la_tadharni_fardan" to DuaText("ज़कारियाचो दुआ (ए. एस.)-म्हाका एकटे सोडचो न्हय", "म्हज्या देवा, म्हाका एकटे सोडचो न्हय, आनी तूं सगळ्यांत बरो वारसदार.", "भुरगीं सोदपी लोकां खातीर.", "ह्या दुआ वरवीं अल्लाहान याह्या (ए. एस.) दिली."),
        "dua_q_munzalan_mubarakan" to DuaText("एक धन्य लँडिंग सुवात", "म्हज्या देवा, म्हाका एका आशीर्वादीत देंवपाच्या सुवातेर देंवपाक दे, आनी तूं जमनीचेर हाडपी लोकां मदीं सगळ्यांत बरो.", "नव्या घरांत वचतना वा खंय तरी थांबतना-नूह (ए. एस.) ची दुआ.", "नव्या जाग्यार आशीर्वाद दिवपा खातीर दुआ."),
        "dua_q_amanna_faghfir" to DuaText("आमी मानतात, देखून आमकां माफ कर.", "म्हज्या प्रभू, आमी विश्वास दवरला, देखून आमकां माफ कर आनी आमचेर दया कर, आनी तूं दयाळू लोकां मदीं सगळ्यांत बरो.", "अल्लाहच्या धर्मीक सेवकांची दुआ.", "क्षमा आनी दया खातीर एक व्यापक दुआ."),
        "dua_q_isrif_jahannam" to DuaText("नरकांतली ख्यास्त टाळ", "म्हज्या देवा, नरकाची ख्यास्त आमसावन टाळ. खरें म्हणल्यार ताची ख्यास्त सदांच आसता. खरें म्हणल्यार ती एक वायट वसणूक आनी रावपाची सुवात.", "परम करुणामायाच्या सेवकांची दुआ ('इबादत-अर-रहमान).", "नरकांतल्यान आलाशिरो घेवपा खातीर कुराणची दुआ."),
        "dua_q_hab_li_hukman" to DuaText("इब्राहिम (अ. स.)-बुध्दि आनी जन्नत", "म्हज्या देवा, म्हाका बुध्दिमानपण दिवचें आनी धर्मीकां वांगडा म्हजे वांगडा मेळचें, उपरांतच्या पिळग्यां मदीं म्हाका सन्मानजनक उल्लेख दिवचो, आनी म्हाका आनंद बागेच्या वारसदारां मदीं हाडचो.", "बुद्धी मागप, धर्मीक आनी स्वर्ग हांची कंपनी.", "इब्राहिम (ए. एस.) हाचें एक व्यापक दुआ."),
    )
}
